// Package cli holds the hand-written transaction commands of x/randomness; the
// queries are generated by autocli.
package cli

import (
	"bytes"
	"encoding/hex"
	"fmt"

	"github.com/cosmos/cosmos-sdk/client"
	"github.com/cosmos/cosmos-sdk/client/flags"
	"github.com/cosmos/cosmos-sdk/client/tx"
	sdk "github.com/cosmos/cosmos-sdk/types"
	"github.com/spf13/cobra"

	"github.com/saicon-network/saicon/chain/crypto/vrf"
	"github.com/saicon-network/saicon/chain/x/randomness/types"
)

// FlagVrfKeyFile names the VRF key file flag.
const FlagVrfKeyFile = "vrf-key-file"

// NewSubmitVrfCmd submits the --from validator's VRF output for the current
// round when its window is open, the validator is its entity's designated
// submitter and nothing was submitted yet; otherwise it prints why and exits 0.
func NewSubmitVrfCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "submit-vrf --vrf-key-file <file> --from <operator>",
		Short: "Submit your validator's VRF proof for the current randomness round",
		Long: "Submit the VRF proof of the --from validator for the current round, made locally with the key in " +
			"--vrf-key-file over the client's chain id, the round number and the round input. When there is " +
			"nothing to do (the window is not open, the validator is not designated this round, or its entity " +
			"already submitted) the command prints the reason and exits 0 without sending a transaction. " +
			"The chain accepts a submission from the window's first height O, but with --gas auto the " +
			"simulation runs at the latest height, and a simulation at height O-1 is refused. Clients " +
			"should submit from O+1; a submitter loop gets there by retrying.",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			clientCtx, err := client.GetClientTxContext(cmd)
			if err != nil {
				return err
			}
			path, err := cmd.Flags().GetString(FlagVrfKeyFile)
			if err != nil {
				return err
			}
			key, err := vrf.LoadKeyFile(path)
			if err != nil {
				return err
			}

			res, err := types.NewQueryClient(clientCtx).Round(cmd.Context(), &types.QueryRoundRequest{})
			if err != nil {
				return err
			}
			node, err := clientCtx.GetNode()
			if err != nil {
				return err
			}
			st, err := node.Status(cmd.Context())
			if err != nil {
				return err
			}
			round := res.Round
			// The transaction lands in a block after the latest one.
			if round.Status != types.RoundStatus_ROUND_STATUS_OPEN || st.SyncInfo.LatestBlockHeight+1 >= round.RotationHeight {
				return say(cmd, "window closed: round %d is not accepting submissions", round.Number)
			}

			from := sdk.ValAddress(clientCtx.GetFromAddress()).String()
			var entry *types.PoolEntry
			for i := range res.Pool {
				if res.Pool[i].Validator == from {
					entry = &res.Pool[i]
					break
				}
			}
			if entry == nil {
				return say(cmd, "not designated this round: %s is not the designated submitter of a pool entity", from)
			}
			for _, s := range res.Submissions {
				if s.EntityId == entry.EntityId {
					return say(cmd, "already submitted: entity %s has a submission for round %d", entry.EntityId, round.Number)
				}
			}
			bound, err := types.DecodeHex(entry.VrfPublicKey, vrf.PublicKeySize)
			if err != nil {
				return err
			}
			if !bytes.Equal(key.PublicKey(), bound) {
				return fmt.Errorf("the key file is not the key bound for this round")
			}
			input, err := types.DecodeHex(round.Input, types.InputHexLen/2)
			if err != nil {
				return err
			}

			proof := key.Prove(types.RoundAlpha(clientCtx.ChainID, round.Number, input))
			msg := &types.MsgSubmitVrf{
				Operator: clientCtx.GetFromAddress().String(),
				Round:    round.Number,
				Proof:    hex.EncodeToString(proof),
			}
			return tx.GenerateOrBroadcastTxCLI(clientCtx, cmd.Flags(), msg)
		},
	}
	flags.AddTxFlagsToCmd(cmd)
	cmd.Flags().String(FlagVrfKeyFile, "", "path to the VRF key file written by 'saicond vrf keygen'")
	_ = cmd.MarkFlagRequired(FlagVrfKeyFile)
	return cmd
}

// say prints a one-line reason on stdout and succeeds.
func say(cmd *cobra.Command, format string, args ...any) error {
	_, err := fmt.Fprintf(cmd.OutOrStdout(), format+"\n", args...)
	return err
}
